//! XYZ / multi-frame XYZ (trajectory) file format.
//!
//! The XYZ format carries no bond information: each frame is an atom-count
//! line, a free-form comment line, then `element x y z` rows (Å). A
//! multi-frame ("trajectory") XYZ file is just several such frames
//! concatenated back-to-back with no separator between them -- each frame
//! is self-delimiting via its own atom-count line.
//!
//! ```text
//! 3
//! water, generated by chematic
//! O    0.00000000    0.00000000    0.00000000
//! H    0.75860000    0.00000000    0.50428400
//! H    0.75860000    0.00000000   -0.50428400
//! ```
//!
//! # Design decisions
//!
//! **Explicit hydrogens are kept as ordinary atoms, not folded into
//! `implicit_hcount()`.** `chematic_core::Molecule` normally represents only
//! heavy atoms (see the crate-level docs), but XYZ has no such concept --
//! every line in the file is a literal atom with a literal coordinate,
//! hydrogen included. Folding an XYZ `H` row into implicit-H bookkeeping
//! would silently discard that atom's real 3D position, defeating the
//! point of this format (conformer/QM coordinate exchange -- specifically
//! the experimental-conformer-RMSD benchmark fixtures this module exists to
//! support). [`XyzFrame::to_molecule`] therefore adds every atom in the
//! file, including H, as an explicit graph node in file order -- the same
//! treatment this crate's SDF/MOL reader already gives explicit H atoms
//! present in a V2000 atom block.
//!
//! **No connectivity or bond-order inference, not even opt-in.** XYZ has no
//! bonds. [`XyzFrame::to_molecule`] always returns a `Molecule` with zero
//! bonds; this module never guesses bonds from interatomic distance and
//! never guesses bond order. Distance-based connectivity inference belongs
//! in a separate operation; these format readers do not invoke it.
//!
//! # Extended XYZ (extxyz)
//!
//! The functions above ([`parse_xyz`], [`XyzReader`], [`write_xyz`], ...)
//! never interpret the comment line -- it is always kept verbatim as one
//! opaque `String` on [`XyzFrame::comment`].
//!
//! [`parse_extxyz`] / [`ExtxyzReader`] / [`write_extxyz`] are a *separate*
//! entry point over the same [`XyzFrame`] type that additionally
//! understands the ASE-style extended-XYZ comment line: a sequence of
//! `key=value` pairs (quoted values may contain spaces), where two keys are
//! special-cased into typed fields:
//!
//! - `Lattice="ax ay az bx by bz cx cy cz"` -- a 3x3 cell matrix, row-major
//!   -> [`XyzFrame::lattice`].
//! - `Properties=species:S:1:pos:R:3[:name:type:count]*` -- the per-atom
//!   column layout. `species`/`pos` always map onto
//!   [`XyzAtom::element`]/`x,y,z` (this crate requires them first, in that
//!   order, matching every ASE-written extxyz file); any further columns
//!   (e.g. `forces:R:3`, `charge:R:1`) become [`XyzFrame::properties`].
//!   When `Properties` is absent, the default `species:S:1:pos:R:3` applies
//!   -- this is what makes an ordinary XYZ file parse as a valid,
//!   zero-extra-property extxyz frame too.
//!
//! Every other `key=value` pair (`energy=...`, `pbc=...`, arbitrary
//! metadata) is kept, in first-seen order, on [`XyzFrame::info`].
//!
//! A comment line containing no `=` at all is treated as an ordinary,
//! unstructured comment (`lattice: None`, `properties: []`, `info: []`) --
//! this is the case that keeps a plain XYZ file's comment line
//! byte-identical through the extxyz reader/writer (see [`write_extxyz`]).
//! Once any `=` is present, the whole line must parse as `key=value`
//! tokens or [`parse_extxyz`] fails closed.

use std::collections::HashSet;

use chematic_3d::xyz::element_from_xyz_symbol;
use chematic_core::{Atom, Element, Molecule, MoleculeBuilder};

/// The declared type of an extended-XYZ `Properties=` column
/// (`R`=real, `I`=integer, `S`=string, `L`=logical).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum XyzPropertyKind {
    Real,
    Integer,
    String,
    Logical,
}

/// A single per-atom scalar value in an extended-XYZ property column.
#[derive(Debug, Clone, PartialEq)]
pub enum XyzValue {
    Real(f64),
    Integer(i64),
    /// Written as a single unquoted whitespace-delimited token (matching
    /// how [`parse_extxyz`] reads an `S`-typed atom-row column): a value
    /// containing whitespace round-trips through [`write_extxyz`] as *more
    /// than one* atom-row token, desyncing every column after it on
    /// reparse. `write_extxyz` does not check for this (only
    /// [`XyzFrame::info`]/[`XyzProperty::name`] are validated, see
    /// `validate_extxyz_writable`) -- avoid whitespace in `Str` property
    /// values when hand-building a frame. Not reachable from the
    /// Python/WASM `to_extxyz` bindings, which only accept real-valued
    /// (`R`) properties.
    Str(String),
    Logical(bool),
}

/// One extended-XYZ per-atom property column beyond `species`/`pos`
/// (e.g. `forces:R:3`, `charge:R:1`), as declared in the frame's
/// `Properties=` key.
#[derive(Debug, Clone, PartialEq)]
pub struct XyzProperty {
    pub name: String,
    pub kind: XyzPropertyKind,
    /// Number of scalar components per atom (e.g. 3 for `forces:R:3`).
    pub count: usize,
    /// `values[atom_index]` has length `count`, same atom order as
    /// [`XyzFrame::atoms`].
    pub values: Vec<Vec<XyzValue>>,
}

/// One atom row in an XYZ frame: element + Cartesian coordinates (Å).
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct XyzAtom {
    pub element: Element,
    pub x: f64,
    pub y: f64,
    pub z: f64,
}

/// A single parsed XYZ frame: atom rows plus the frame's comment line.
#[derive(Debug, Clone, PartialEq)]
pub struct XyzFrame {
    /// Atoms in file order.
    pub atoms: Vec<XyzAtom>,
    /// The frame's comment line (line 2 of the frame), verbatim. May be
    /// empty. Always populated by [`parse_xyz`]/[`parse_extxyz`] alike.
    /// [`write_extxyz`] uses this verbatim only when `lattice`, `properties`
    /// and `info` are all empty -- see the module-level "Extended XYZ" docs.
    pub comment: String,
    /// Extended-XYZ `Lattice=` cell matrix (row-major 3x3), if present.
    /// Always `None` for frames from [`parse_xyz`]/[`XyzReader`].
    pub lattice: Option<[f64; 9]>,
    /// Extended-XYZ per-atom property columns beyond `species`/`pos` (which
    /// map onto [`XyzAtom`] itself), e.g. `forces:R:3` or `charge:R:1`.
    /// Always empty for frames from [`parse_xyz`]/[`XyzReader`].
    pub properties: Vec<XyzProperty>,
    /// Extended-XYZ frame-level `key=value` metadata other than
    /// `Lattice`/`Properties` (e.g. `energy`, `pbc`, `config_type`), in
    /// first-seen order. Always empty for frames from
    /// [`parse_xyz`]/[`XyzReader`].
    pub info: Vec<(String, String)>,
}

impl XyzFrame {
    /// Build a `Molecule` from this frame: every atom (including hydrogen)
    /// becomes an explicit graph node, in file order, with zero bonds. See
    /// the module-level docs for why H is kept explicit here.
    pub fn to_molecule(&self) -> Molecule {
        let mut builder = MoleculeBuilder::new();
        for atom in &self.atoms {
            builder.add_atom(Atom::new(atom.element));
        }
        builder.build()
    }

    /// Cartesian coordinates (Å), in the same atom order as `to_molecule()`.
    pub fn coords(&self) -> Vec<(f64, f64, f64)> {
        self.atoms.iter().map(|a| (a.x, a.y, a.z)).collect()
    }
}

/// Errors that can occur while parsing an XYZ frame.
#[derive(Debug, Clone, PartialEq)]
pub enum XyzError {
    /// A configured input, frame, or line limit was exceeded.
    ResourceLimit {
        resource: &'static str,
        actual: usize,
        limit: usize,
    },
    /// The atom-count line (line 1) is missing or not a valid non-negative integer.
    InvalidCountLine { line: usize, raw: String },
    /// The comment line (line 2) is missing (input ended after the count line).
    MissingCommentLine,
    /// An atom row does not have the form `element x y z`.
    InvalidAtomLine { line: usize, detail: String },
    /// An atom row's element symbol is not recognised.
    UnknownElement { symbol: String, line: usize },
    /// A coordinate value parsed but is NaN or infinite.
    NonFiniteCoordinate {
        line: usize,
        axis: &'static str,
        raw: String,
    },
    /// Fewer atom rows were present than the count line declared (input
    /// ended early). The opposite case -- *more* rows than declared -- is
    /// not representable as this variant: since frames have no separator,
    /// the extra rows are simply read as the start of the next frame, and
    /// surface (if at all) as `InvalidCountLine` when that next "count
    /// line" fails to parse as an integer.
    AtomCountMismatch { declared: usize, found: usize },
    /// [`parse_extxyz`] only: a comment-line token has an empty key (a
    /// stray `=` with nothing before it). A bare key with no `=value` at
    /// all is *not* this error -- it is a valid implicit boolean flag,
    /// defaulting to `"T"` (matches ASE's own convention).
    InvalidInfoField { line: usize, detail: String },
    /// [`parse_extxyz`] only: a quoted value (`key="..."`) in the comment
    /// line has no closing quote.
    UnterminatedQuote { line: usize, key: String },
    /// [`parse_extxyz`] only: the same key appears twice in the comment
    /// line.
    DuplicateInfoKey { line: usize, key: String },
    /// [`parse_extxyz`] only: `Lattice=` does not contain exactly 9
    /// whitespace-separated finite numbers.
    InvalidLattice { line: usize, detail: String },
    /// [`parse_extxyz`] only: `Properties=` is malformed, or does not start
    /// with `species:S:1:pos:R:3`.
    InvalidProperties { line: usize, detail: String },
    /// [`parse_extxyz`] only: an atom row's whitespace-token count doesn't
    /// match what the frame's `Properties` columns declare.
    PropertyColumnMismatch {
        line: usize,
        expected: usize,
        found: usize,
    },
    /// [`parse_extxyz`] only: a per-atom property value (beyond
    /// `species`/`pos`) failed to parse as its declared type, or was
    /// non-finite for an `R` column.
    InvalidPropertyValue {
        line: usize,
        property: String,
        raw: String,
    },
    /// [`write_extxyz`]/[`ExtxyzWriter::write_frame`] only: an
    /// `XyzFrame::info` key/value or [`XyzProperty::name`] contains a
    /// character extxyz `key=value` syntax cannot represent (see
    /// [`validate_extxyz_writable`]) -- never produced by this module's own
    /// parsers, only by writing a hand-built `XyzFrame`.
    UnwritableMetadata { detail: String },
}

impl std::fmt::Display for XyzError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::ResourceLimit {
                resource,
                actual,
                limit,
            } => write!(f, "XYZ {resource} exceeds limit {limit} (got {actual})"),
            Self::InvalidCountLine { line, raw } => {
                write!(f, "invalid atom-count line {line}: '{raw}'")
            }
            Self::MissingCommentLine => write!(f, "missing comment line"),
            Self::InvalidAtomLine { line, detail } => {
                write!(f, "invalid atom line {line}: {detail}")
            }
            Self::UnknownElement { symbol, line } => {
                write!(f, "unknown element '{symbol}' at line {line}")
            }
            Self::NonFiniteCoordinate { line, axis, raw } => {
                write!(f, "non-finite {axis} coordinate '{raw}' at line {line}")
            }
            Self::AtomCountMismatch { declared, found } => {
                write!(
                    f,
                    "atom-count line declared {declared} atoms, found {found}"
                )
            }
            Self::InvalidInfoField { line, detail } => {
                write!(f, "invalid extxyz info field at line {line}: {detail}")
            }
            Self::UnterminatedQuote { line, key } => {
                write!(
                    f,
                    "unterminated quoted value for key '{key}' at line {line}"
                )
            }
            Self::DuplicateInfoKey { line, key } => {
                write!(f, "duplicate extxyz info key '{key}' at line {line}")
            }
            Self::InvalidLattice { line, detail } => {
                write!(f, "invalid Lattice at line {line}: {detail}")
            }
            Self::InvalidProperties { line, detail } => {
                write!(f, "invalid Properties at line {line}: {detail}")
            }
            Self::PropertyColumnMismatch {
                line,
                expected,
                found,
            } => {
                write!(
                    f,
                    "atom line {line}: Properties columns declare {expected} value(s), found {found}"
                )
            }
            Self::InvalidPropertyValue {
                line,
                property,
                raw,
            } => {
                write!(
                    f,
                    "invalid value '{raw}' for property '{property}' at line {line}"
                )
            }
            Self::UnwritableMetadata { detail } => {
                write!(f, "cannot write extxyz frame: {detail}")
            }
        }
    }
}

impl std::error::Error for XyzError {}

/// Resource limits for XYZ and Extended XYZ parsing.
#[derive(Debug, Clone, Copy)]
pub struct XyzParseLimits {
    /// Maximum input size in bytes.
    pub max_input_bytes: usize,
    /// Maximum atoms declared in one frame.
    pub max_atoms_per_frame: usize,
    /// Maximum number of frames in an all-frames parse.
    pub max_frames: usize,
    /// Maximum physical line size in bytes.
    pub max_line_bytes: usize,
}

impl Default for XyzParseLimits {
    fn default() -> Self {
        Self {
            max_input_bytes: 1 << 30,
            max_atoms_per_frame: 1_000_000,
            max_frames: 100_000,
            max_line_bytes: 16 << 20,
        }
    }
}

fn validate_xyz_input_limits(text: &str, limits: &XyzParseLimits) -> Result<(), XyzError> {
    if text.len() > limits.max_input_bytes {
        return Err(XyzError::ResourceLimit {
            resource: "input bytes",
            actual: text.len(),
            limit: limits.max_input_bytes,
        });
    }
    for line in text.lines() {
        if line.len() > limits.max_line_bytes {
            return Err(XyzError::ResourceLimit {
                resource: "line bytes",
                actual: line.len(),
                limit: limits.max_line_bytes,
            });
        }
    }
    Ok(())
}

fn validate_xyz_limits(text: &str, limits: &XyzParseLimits) -> Result<(), XyzError> {
    validate_xyz_input_limits(text, limits)?;
    let mut lines = text.lines();
    let mut frames = 0usize;
    while let Some(count_line) = lines.next() {
        let Ok(count) = count_line.trim().parse::<usize>() else {
            break;
        };
        frames = frames.saturating_add(1);
        if frames > limits.max_frames {
            return Err(XyzError::ResourceLimit {
                resource: "frames",
                actual: frames,
                limit: limits.max_frames,
            });
        }
        if count > limits.max_atoms_per_frame {
            return Err(XyzError::ResourceLimit {
                resource: "atoms per frame",
                actual: count,
                limit: limits.max_atoms_per_frame,
            });
        }
        let _ = lines.next();
        for _ in 0..count {
            let _ = lines.next();
        }
    }
    Ok(())
}

/// Parse a single XYZ frame from the start of `text`. Trailing content
/// after the frame (e.g. further frames in a multi-frame trajectory file)
/// is ignored -- use [`XyzReader`] to iterate every frame in a multi-frame
/// file.
pub fn parse_xyz(text: &str) -> Result<XyzFrame, XyzError> {
    parse_xyz_with_limits(text, &XyzParseLimits::default())
}

/// Parse a single XYZ frame while enforcing resource limits.
pub fn parse_xyz_with_limits(text: &str, limits: &XyzParseLimits) -> Result<XyzFrame, XyzError> {
    validate_xyz_limits(text, limits)?;
    parse_one_frame(text).map(|(frame, _rest)| frame)
}

/// Split the next line off the front of `text`. Handles `\n` and `\r\n`
/// line endings and an unterminated final line. Returns `None` only when
/// `text` is entirely empty (no more input, not even a partial line).
///
/// This is the *only* place frame/line boundaries are computed -- earlier
/// revisions of this parser walked lines twice (once via `str::lines()` to
/// consume content, once via a byte-offset recomputation to find the next
/// frame's start) and those two mechanisms could disagree on inputs mixing
/// `\r\n` line endings with a non-`\n`-terminated final line. Tracking the
/// byte offset directly here, in one pass, makes that class of bug
/// unrepresentable.
fn next_line(text: &str) -> Option<(&str, &str)> {
    if text.is_empty() {
        return None;
    }
    match text.find('\n') {
        Some(nl) => Some((text[..nl].trim_end_matches('\r'), &text[nl + 1..])),
        None => Some((text.trim_end_matches('\r'), "")),
    }
}

/// Parse one frame starting at `text`, returning the frame and the
/// remaining unparsed input. Shared by [`parse_xyz`] and [`XyzReader`].
fn parse_one_frame(text: &str) -> Result<(XyzFrame, &str), XyzError> {
    let (count_line, rest) = next_line(text).ok_or(XyzError::InvalidCountLine {
        line: 1,
        raw: String::new(),
    })?;
    let declared: usize = count_line
        .trim()
        .parse()
        .map_err(|_| XyzError::InvalidCountLine {
            line: 1,
            raw: count_line.to_string(),
        })?;

    let (comment_line, mut rest) = next_line(rest).ok_or(XyzError::MissingCommentLine)?;
    let comment = comment_line.to_string();

    let mut atoms = Vec::with_capacity(declared);
    for lineno in (3usize..).take(declared) {
        let Some((raw_line, next_rest)) = next_line(rest) else {
            break;
        };
        rest = next_rest;

        let parts: Vec<&str> = raw_line.split_whitespace().collect();
        if parts.len() < 4 {
            return Err(XyzError::InvalidAtomLine {
                line: lineno,
                detail: format!("expected 'element x y z', got '{raw_line}'"),
            });
        }
        let element =
            element_from_xyz_symbol(parts[0]).ok_or_else(|| XyzError::UnknownElement {
                symbol: parts[0].to_string(),
                line: lineno,
            })?;

        let parse_coord = |raw: &str, axis: &'static str| -> Result<f64, XyzError> {
            let v: f64 = raw.parse().map_err(|_| XyzError::InvalidAtomLine {
                line: lineno,
                detail: format!("cannot parse {axis} coordinate '{raw}'"),
            })?;
            if !v.is_finite() {
                return Err(XyzError::NonFiniteCoordinate {
                    line: lineno,
                    axis,
                    raw: raw.to_string(),
                });
            }
            Ok(v)
        };
        let x = parse_coord(parts[1], "x")?;
        let y = parse_coord(parts[2], "y")?;
        let z = parse_coord(parts[3], "z")?;
        atoms.push(XyzAtom { element, x, y, z });
    }

    if atoms.len() != declared {
        return Err(XyzError::AtomCountMismatch {
            declared,
            found: atoms.len(),
        });
    }

    Ok((
        XyzFrame {
            atoms,
            comment,
            lattice: None,
            properties: Vec::new(),
            info: Vec::new(),
        },
        rest,
    ))
}

/// Iterator over frames in a multi-frame XYZ (trajectory) string.
///
/// Each call to `next()` returns the next [`XyzFrame`], or the first
/// [`XyzError`] encountered. Iteration stops for good after an error --
/// once a frame fails to parse, the byte offset of the *next* frame can no
/// longer be trusted, so `next()` returns `None` on every subsequent call
/// rather than risk mis-parsing garbage as a frame.
pub struct XyzReader<'a> {
    remaining: &'a str,
    limits: XyzParseLimits,
    input_validated: bool,
    frames_read: usize,
}

impl<'a> XyzReader<'a> {
    /// Create a new `XyzReader` over the given multi-frame XYZ string.
    pub fn new(input: &'a str) -> Self {
        Self::with_limits(input, XyzParseLimits::default())
    }

    /// Create an in-memory XYZ reader with explicit resource limits.
    pub fn with_limits(input: &'a str, limits: XyzParseLimits) -> Self {
        Self {
            remaining: input,
            limits,
            input_validated: false,
            frames_read: 0,
        }
    }
}

impl<'a> Iterator for XyzReader<'a> {
    type Item = Result<XyzFrame, XyzError>;

    fn next(&mut self) -> Option<Self::Item> {
        if !self.input_validated {
            self.input_validated = true;
            if let Err(error) = validate_xyz_input_limits(self.remaining, &self.limits) {
                self.remaining = "";
                return Some(Err(error));
            }
        }
        // A run of blank lines between frames is not part of the spec (each
        // frame is self-delimited by its own count line, no separator) but
        // is tolerated here -- some multi-frame XYZ writers leave a
        // trailing blank line at EOF.
        if self.remaining.trim().is_empty() {
            return None;
        }
        let leading_blank =
            self.remaining.len() - self.remaining.trim_start_matches(['\n', '\r']).len();
        self.remaining = &self.remaining[leading_blank..];

        let count_line = next_line(self.remaining)
            .map(|(line, _)| line)
            .unwrap_or("");
        if let Ok(declared) = count_line.trim().parse::<usize>()
            && declared > self.limits.max_atoms_per_frame
        {
            self.remaining = "";
            return Some(Err(XyzError::ResourceLimit {
                resource: "atoms per frame",
                actual: declared,
                limit: self.limits.max_atoms_per_frame,
            }));
        }
        self.frames_read = self.frames_read.saturating_add(1);
        if self.frames_read > self.limits.max_frames {
            self.remaining = "";
            return Some(Err(XyzError::ResourceLimit {
                resource: "frames",
                actual: self.frames_read,
                limit: self.limits.max_frames,
            }));
        }

        match parse_one_frame(self.remaining) {
            Ok((frame, rest)) => {
                self.remaining = rest;
                Some(Ok(frame))
            }
            Err(e) => {
                self.remaining = "";
                Some(Err(e))
            }
        }
    }
}

/// Streaming XYZ iterator over any [`std::io::BufRead`] source.
///
/// At most one frame is retained for parsing. The reader is therefore useful
/// for trajectory files that do not fit in memory; the frame itself is still
/// materialized as an [`XyzFrame`]. Input, line, atom, and frame limits are
/// enforced before the frame is yielded.
pub struct XyzFileReader<R: std::io::BufRead> {
    reader: R,
    block: String,
    line: String,
    limits: XyzParseLimits,
    bytes_read: usize,
    frames_read: usize,
    done: bool,
}

impl<R: std::io::BufRead> XyzFileReader<R> {
    /// Wrap a buffered XYZ source using the default resource limits.
    pub fn new(reader: R) -> Self {
        Self::with_limits(reader, XyzParseLimits::default())
    }

    /// Wrap a buffered XYZ source and enforce input, line, atom, and frame limits.
    pub fn with_limits(reader: R, limits: XyzParseLimits) -> Self {
        Self {
            reader,
            block: String::new(),
            line: String::new(),
            limits,
            bytes_read: 0,
            frames_read: 0,
            done: false,
        }
    }

    fn read_line(&mut self) -> Result<bool, XyzError> {
        self.line.clear();
        let bytes =
            self.reader
                .read_line(&mut self.line)
                .map_err(|error| XyzError::InvalidAtomLine {
                    line: 0,
                    detail: format!("I/O error: {error}"),
                })?;
        if bytes == 0 {
            return Ok(false);
        }
        self.bytes_read = self.bytes_read.saturating_add(bytes);
        if self.bytes_read > self.limits.max_input_bytes {
            return Err(XyzError::ResourceLimit {
                resource: "input bytes",
                actual: self.bytes_read,
                limit: self.limits.max_input_bytes,
            });
        }
        let length = self.line.trim_end_matches(['\n', '\r']).len();
        if length > self.limits.max_line_bytes {
            return Err(XyzError::ResourceLimit {
                resource: "line bytes",
                actual: length,
                limit: self.limits.max_line_bytes,
            });
        }
        Ok(true)
    }
}

impl<R: std::io::BufRead> Iterator for XyzFileReader<R> {
    type Item = Result<XyzFrame, XyzError>;

    fn next(&mut self) -> Option<Self::Item> {
        if self.done {
            return None;
        }

        // Skip optional blank separators between trajectory frames.
        loop {
            match self.read_line() {
                Ok(true) if !self.line.trim().is_empty() => break,
                Ok(true) => continue,
                Ok(false) => {
                    self.done = true;
                    return None;
                }
                Err(error) => {
                    self.done = true;
                    return Some(Err(error));
                }
            }
        }

        let count_line = self.line.clone();
        let declared = match count_line.trim().parse::<usize>() {
            Ok(count) => count,
            Err(_) => {
                self.done = true;
                return Some(Err(XyzError::InvalidCountLine {
                    line: 1,
                    raw: count_line.trim_end().to_string(),
                }));
            }
        };
        if declared > self.limits.max_atoms_per_frame {
            self.done = true;
            return Some(Err(XyzError::ResourceLimit {
                resource: "atoms per frame",
                actual: declared,
                limit: self.limits.max_atoms_per_frame,
            }));
        }
        self.frames_read = self.frames_read.saturating_add(1);
        if self.frames_read > self.limits.max_frames {
            self.done = true;
            return Some(Err(XyzError::ResourceLimit {
                resource: "frames",
                actual: self.frames_read,
                limit: self.limits.max_frames,
            }));
        }

        self.block.clear();
        self.block.push_str(&count_line);
        for _ in 0..declared.saturating_add(1) {
            match self.read_line() {
                Ok(true) => self.block.push_str(&self.line),
                Ok(false) => {
                    self.done = true;
                    return Some(Err(XyzError::AtomCountMismatch {
                        declared,
                        found: self.block.lines().count().saturating_sub(2),
                    }));
                }
                Err(error) => {
                    self.done = true;
                    return Some(Err(error));
                }
            }
        }

        match parse_one_frame(&self.block) {
            Ok((frame, _)) => Some(Ok(frame)),
            Err(error) => {
                self.done = true;
                Some(Err(error))
            }
        }
    }
}

/// One bounded, input-ordered batch from [`XyzBatchReader`].
pub struct XyzBatch {
    /// Zero-based batch sequence number.
    pub sequence: usize,
    /// Frames in source order; parse failures are retained in place.
    pub frames: Vec<Result<XyzFrame, XyzError>>,
}

impl XyzBatch {
    pub fn len(&self) -> usize {
        self.frames.len()
    }

    pub fn is_empty(&self) -> bool {
        self.frames.is_empty()
    }
}

/// Deterministic progress snapshot for a bounded XYZ batch stream.
#[derive(Debug, Clone, Copy, PartialEq, Eq, serde::Serialize)]
pub struct XyzBatchProgress {
    pub schema_version: u32,
    /// `running`, `complete`, or `cancelled`.
    pub status: &'static str,
    pub batch_size: usize,
    pub frames_emitted: usize,
    pub batches_emitted: usize,
}

/// Pull-based bounded batch reader over any [`std::io::BufRead`] XYZ source.
///
/// Pulling the next item is the backpressure boundary: no background queue is
/// created. Cancellation stops before the next batch is read.
pub struct XyzBatchReader<R: std::io::BufRead> {
    inner: XyzFileReader<R>,
    batch_size: usize,
    cancelled: bool,
    exhausted: bool,
    frames_emitted: usize,
    batches_emitted: usize,
}

impl<R: std::io::BufRead> XyzBatchReader<R> {
    pub fn new(reader: R, batch_size: usize) -> Self {
        assert!(batch_size > 0, "batch_size must be greater than zero");
        Self::with_limits(reader, batch_size, XyzParseLimits::default())
    }

    pub fn with_limits(reader: R, batch_size: usize, limits: XyzParseLimits) -> Self {
        assert!(batch_size > 0, "batch_size must be greater than zero");
        Self {
            inner: XyzFileReader::with_limits(reader, limits),
            batch_size,
            cancelled: false,
            exhausted: false,
            frames_emitted: 0,
            batches_emitted: 0,
        }
    }

    pub fn cancel(&mut self) {
        self.cancelled = true;
    }

    pub fn is_cancelled(&self) -> bool {
        self.cancelled
    }

    pub fn progress(&self) -> XyzBatchProgress {
        XyzBatchProgress {
            schema_version: 1,
            status: if self.cancelled {
                "cancelled"
            } else if self.exhausted {
                "complete"
            } else {
                "running"
            },
            batch_size: self.batch_size,
            frames_emitted: self.frames_emitted,
            batches_emitted: self.batches_emitted,
        }
    }

    pub fn manifest_json(&self) -> String {
        serde_json::to_string(&self.progress()).expect("XYZ progress is serializable")
    }
}

impl<R: std::io::BufRead> Iterator for XyzBatchReader<R> {
    type Item = XyzBatch;

    fn next(&mut self) -> Option<Self::Item> {
        if self.cancelled || self.exhausted {
            return None;
        }
        let mut frames = Vec::with_capacity(self.batch_size);
        while frames.len() < self.batch_size {
            match self.inner.next() {
                Some(frame) => frames.push(frame),
                None => {
                    self.exhausted = true;
                    break;
                }
            }
        }
        if frames.is_empty() {
            return None;
        }
        let sequence = self.batches_emitted;
        self.frames_emitted += frames.len();
        self.batches_emitted += 1;
        Some(XyzBatch { sequence, frames })
    }
}

/// Streaming Extended XYZ iterator over any [`std::io::BufRead`] source.
///
/// One complete frame is retained at a time. The frame boundary is read from
/// its atom count, so a trajectory can be processed without loading the
/// complete file into memory.
pub struct ExtxyzFileReader<R: std::io::BufRead> {
    reader: R,
    block: String,
    line: String,
    limits: XyzParseLimits,
    bytes_read: usize,
    frames_read: usize,
    done: bool,
}

impl<R: std::io::BufRead> ExtxyzFileReader<R> {
    pub fn new(reader: R) -> Self {
        Self::with_limits(reader, XyzParseLimits::default())
    }

    pub fn with_limits(reader: R, limits: XyzParseLimits) -> Self {
        Self {
            reader,
            block: String::new(),
            line: String::new(),
            limits,
            bytes_read: 0,
            frames_read: 0,
            done: false,
        }
    }

    fn read_line(&mut self) -> Result<bool, XyzError> {
        self.line.clear();
        let bytes =
            self.reader
                .read_line(&mut self.line)
                .map_err(|error| XyzError::InvalidAtomLine {
                    line: 0,
                    detail: format!("I/O error: {error}"),
                })?;
        if bytes == 0 {
            return Ok(false);
        }
        self.bytes_read = self.bytes_read.saturating_add(bytes);
        if self.bytes_read > self.limits.max_input_bytes {
            return Err(XyzError::ResourceLimit {
                resource: "input bytes",
                actual: self.bytes_read,
                limit: self.limits.max_input_bytes,
            });
        }
        let length = self.line.trim_end_matches(['\n', '\r']).len();
        if length > self.limits.max_line_bytes {
            return Err(XyzError::ResourceLimit {
                resource: "line bytes",
                actual: length,
                limit: self.limits.max_line_bytes,
            });
        }
        Ok(true)
    }
}

impl<R: std::io::BufRead> Iterator for ExtxyzFileReader<R> {
    type Item = Result<XyzFrame, XyzError>;

    fn next(&mut self) -> Option<Self::Item> {
        if self.done {
            return None;
        }
        loop {
            match self.read_line() {
                Ok(true) if !self.line.trim().is_empty() => break,
                Ok(true) => continue,
                Ok(false) => {
                    self.done = true;
                    return None;
                }
                Err(error) => {
                    self.done = true;
                    return Some(Err(error));
                }
            }
        }

        let count_line = self.line.clone();
        let declared = match count_line.trim().parse::<usize>() {
            Ok(count) => count,
            Err(_) => {
                self.done = true;
                return Some(Err(XyzError::InvalidCountLine {
                    line: 1,
                    raw: count_line.trim_end().to_string(),
                }));
            }
        };
        if declared > self.limits.max_atoms_per_frame {
            self.done = true;
            return Some(Err(XyzError::ResourceLimit {
                resource: "atoms per frame",
                actual: declared,
                limit: self.limits.max_atoms_per_frame,
            }));
        }
        self.frames_read = self.frames_read.saturating_add(1);
        if self.frames_read > self.limits.max_frames {
            self.done = true;
            return Some(Err(XyzError::ResourceLimit {
                resource: "frames",
                actual: self.frames_read,
                limit: self.limits.max_frames,
            }));
        }

        self.block.clear();
        self.block.push_str(&count_line);
        for _ in 0..declared.saturating_add(1) {
            match self.read_line() {
                Ok(true) => self.block.push_str(&self.line),
                Ok(false) => {
                    self.done = true;
                    return Some(Err(XyzError::AtomCountMismatch {
                        declared,
                        found: self.block.lines().count().saturating_sub(2),
                    }));
                }
                Err(error) => {
                    self.done = true;
                    return Some(Err(error));
                }
            }
        }

        match parse_one_frame_ext(&self.block) {
            Ok((frame, _)) => Some(Ok(frame)),
            Err(error) => {
                self.done = true;
                Some(Err(error))
            }
        }
    }
}

